from statistics import median
history = {"park": [40, 55, 38, 61, 47] * 6, "choi": [300, 280, 310, 295, 320] * 6}
today = {"park": 900, "choi": 340}
for u, h in history.items():
    m = median(h)
    ratio = today[u] / m
    print(u, "중앙값", m, "오늘", today[u], f"배수 {ratio:.1f}", "경보" if ratio >= 5 else "-")

# park 중앙값 47.0 오늘 900 배수 19.1 경보
# choi 중앙값 300.0 오늘 340 배수 1.1 -
